#!/usr/bin/env python3
"""生成单测用的脱敏阈值表样例（含规则编译用的各类"不整齐"行）。

样例刻意覆盖规则引擎要处理的每一类边界：

* 正常行（通用规则）；
* 按**性别 / 年龄段**分档的多行（择一）；
* 同一项目**两个生效期**（版本切换）；
* 闭开区间语义（``≤`` / ``>=``）；
* 缺口四类：方向缺失 / 阈值非数值 / 区间反写 / 缺单位；
* 分档写法看不懂（适用性别 / 年龄段无法识别）；
* 同项目同分档**互斥**阈值（拒绝自动判定）。

    python3 tests/fixtures/build_rules_fixture.py
"""

from __future__ import annotations

from pathlib import Path

from openpyxl import Workbook

HEADER = [
    "项目码",
    "项目名",
    "单位",
    "低危急值",
    "高危急值",
    "参考区间",
    "生效日期",
    "失效日期",
    "版本号",
    "适用性别",
    "适用年龄段",
]

ROWS = [
    # 通用规则
    ["718-7", "血红蛋白", "g/L", 30, 200, "115-150", "2026-01-01", None, "测试 v1.0", "", ""],
    # 闭开区间：≤20 判危急、>=1000 判危急
    ["777-3", "血小板计数", "10*9/L", "≤20", ">=1000", "125-350", "2026-01-01", None, "测试 v1.0", "", ""],
    # 同项目按性别 + 年龄段分档（男女阈值不同，择一结果可观察）
    ["2345-7", "葡萄糖", "mmol/L", 2.8, 22.3, "3.9-6.1", "2026-01-01", None, "测试 v1.0", "男", "18-60"],
    ["2345-7", "葡萄糖", "mmol/L", 2.8, 23.0, "3.9-6.1", "2026-01-01", None, "测试 v1.0", "女", "18-60"],
    # 同项目的新版本（2026-02-01 起生效）
    ["2345-7", "葡萄糖", "mmol/L", 3.0, 25.0, "3.9-6.1", "2026-02-01", None, "测试 v2.0", "", ""],
    # 版本空档：生效期在 2026-01-01 与 2026-02-01 之间
    ["2823-3", "钾", "mmol/L", 2.8, 6.5, "3.5-5.3", "2026-01-01", "2026-01-15", "测试 v0.9", "", ""],
    # 缺口：方向缺失（两侧阈值都空）
    ["8888-8", "缺方向项目", "mmol/L", None, None, "1-2", "2026-01-01", None, "测试 v1.0", "", ""],
    # 缺口：阈值非数值（写了但解析不出数值）
    ["6666-6", "阈值非数值项目", "mmol/L", "危急", 10, "1-2", "2026-01-01", None, "测试 v1.0", "", ""],
    # 缺口：区间反写（低危值 >= 高危值）
    ["5555-5", "区间反写项目", "mmol/L", 100, 10, "1-2", "2026-01-01", None, "测试 v1.0", "", ""],
    # 缺口：缺单位
    ["4444-4", "缺单位项目", "", 1, 2, "1-2", "2026-01-01", None, "测试 v1.0", "", ""],
    # 缺口：适用人群写法看不懂
    ["3333-3", "人群写法项目", "mmol/L", 1, 2, "1-2", "2026-01-01", None, "测试 v1.0", "孕产妇", ""],
    # 互斥：同项目、同分档、同生效期，但阈值不一致
    ["2222-2", "互斥阈值项目", "mmol/L", 1.0, 5.0, "1-2", "2026-01-01", None, "测试 v1.0", "男", "18-60"],
    ["2222-2", "互斥阈值项目", "mmol/L", 2.0, 6.0, "1-2", "2026-01-01", None, "测试 v1.0", "男", "18-60"],
]


def build(dest: Path) -> Path:
    workbook = Workbook()
    sheet = workbook.active
    sheet.title = "危急值阈值表"
    sheet.append(HEADER)
    for row in ROWS:
        sheet.append(row)
    dest.parent.mkdir(parents=True, exist_ok=True)
    workbook.save(dest)
    return dest


if __name__ == "__main__":
    target = Path(__file__).resolve().parent / "脱敏样例规则阈值表.xlsx"
    print("已生成", build(target))
